insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('weekly-energy-ledger', 'Weekly Energy Ledger', 'worksheet'::resource_kind, 'A one-week sheet where a client lists activities and rates what each gives or costs in energy.', 'Use it to help a client see where energy goes and plan a steadier week.', array['Adults']::text[], 'One week', 'Have the client fill in two or three days in session so the ratings feel concrete. Look for the activities that cost a lot and give nothing back, and for ones that refill them. Plan one small swap together instead of overhauling the week.', '[{"id": "f0", "type": "textarea", "label": "Activities that took a lot of energy this week"}, {"id": "f1", "type": "textarea", "label": "Activities that gave energy back"}, {"id": "f2", "type": "textarea", "label": "One thing I could move, shorten or share"}, {"id": "f3", "type": "textarea", "label": "One refilling thing I will add this week"}]'::jsonb, array['energy', 'planning', 'weekly review']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('unsent-letter-template', 'Unsent Letter Template', 'worksheet'::resource_kind, 'A structured page for writing a letter to someone the client will not send, with a closing step to put it away.', 'Use it to give a client a contained place to say what has gone unsaid.', array['Adults']::text[], '30 minutes', 'Offer this when a client carries words they cannot say to someone. Frame it as writing for themselves, with no plan to send. Agree beforehand how the letter will be kept or let go of, and leave time to check in on how they feel afterward.', '[{"id": "f0", "type": "textarea", "label": "Who the letter is to"}, {"id": "f1", "type": "textarea", "label": "What I wish they knew"}, {"id": "f2", "type": "textarea", "label": "What I needed from them"}, {"id": "f3", "type": "textarea", "label": "What I want to say to close it"}, {"id": "f4", "type": "textarea", "label": "How I will put this letter away"}]'::jsonb, array['narrative', 'processing', 'expression']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('decision-values-compass', 'Decision Values Compass', 'worksheet'::resource_kind, 'A one-page sheet for weighing a decision against what matters most to the client.', 'Use it to help a client check a choice against their own values.', array['Adults']::text[], '20 minutes', 'Useful when a client is stuck between two reasonable options. Ask them to name values first, then compare each option against them. The sheet does not choose for them; it makes the trade-offs visible so they can decide.', '[{"id": "f0", "type": "textarea", "label": "The decision I am facing"}, {"id": "f1", "type": "textarea", "label": "Three things that matter most to me here"}, {"id": "f2", "type": "textarea", "label": "How option one fits those"}, {"id": "f3", "type": "textarea", "label": "How option two fits those"}, {"id": "f4", "type": "textarea", "label": "What I notice when I read both"}, {"id": "f5", "type": "textarea", "label": "The smallest next step"}]'::jsonb, array['decision making', 'values', 'clarity']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('boundary-sentence-workshop', 'Boundary Sentence Workshop', 'worksheet'::resource_kind, 'A fill-in page for drafting a short, kind boundary statement and a follow-through plan.', 'Use it to help a client prepare words and actions for a boundary.', array['Adults']::text[], '25 minutes', 'Clients often know the boundary but freeze on the wording. Draft the sentence together, then rehearse it aloud. Spend time on the follow-through line, since the plan for what they will do matters as much as the sentence.', '[{"id": "f0", "type": "textarea", "label": "The situation where I need a boundary"}, {"id": "f1", "type": "textarea", "label": "What I am willing and not willing to do"}, {"id": "f2", "type": "textarea", "label": "My boundary in one sentence"}, {"id": "f3", "type": "textarea", "label": "What I will do if it is crossed"}, {"id": "f4", "type": "textarea", "label": "Who can back me up"}]'::jsonb, array['boundaries', 'assertiveness', 'communication']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('sleep-wind-down-log', 'Sleep Wind-Down Log', 'worksheet'::resource_kind, 'A seven-night log of evening habits, wind-down steps and how settled the client felt at bedtime.', 'Use it to help a client spot which evening habits ease their way into sleep.', array['Adults']::text[], 'One week', 'This is a plain log of habits, not a sleep program. Review it for patterns such as screens, caffeine timing or racing thoughts at bedtime. Pick one habit to adjust and keep the rest steady so the change is easy to read.', '[{"id": "f0", "type": "textarea", "label": "What I did in the last hour before bed"}, {"id": "f1", "type": "textarea", "label": "What helped me settle"}, {"id": "f2", "type": "textarea", "label": "What kept me wired"}, {"id": "f3", "type": "textarea", "label": "How settled I felt at lights out"}, {"id": "f4", "type": "textarea", "label": "One change to try tomorrow night"}]'::jsonb, array['sleep', 'routines', 'monitoring']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('cost-of-thinking-traps-ledger', 'Cost of Thinking Traps Ledger', 'cbt'::resource_kind, 'A two-column ledger comparing what a recurring thought costs a client with what it gives.', 'Use it to help a client weigh the usefulness of a thought, not only its truth.', array['Adults']::text[], '25 minutes', 'Some thoughts are hard to disprove but plainly unhelpful. Ask what believing it buys and what it costs, then ask what a more useful stance might be. Keep the tone curious and avoid arguing with the client.', '[{"id": "f0", "type": "textarea", "label": "A thought that keeps coming back"}, {"id": "f1", "type": "textarea", "label": "What this thought gets me"}, {"id": "f2", "type": "textarea", "label": "What this thought costs me"}, {"id": "f3", "type": "textarea", "label": "A more useful way to hold it"}, {"id": "f4", "type": "textarea", "label": "What I would do differently"}]'::jsonb, array['thought challenging', 'cognitive restructuring', 'pros and cons']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('worst-best-most-likely-chart', 'Worst, Best, Most Likely Chart', 'cbt'::resource_kind, 'A three-row chart for predicting the worst, best and most likely outcome of a worry, then checking later.', 'Use it to help a client widen a narrow prediction and compare it with what happened.', array['Adults']::text[], '20 minutes', 'Fill in the three rows in session, then have the client rate how much they believe each. After the event, review what really happened. Pay attention to how often the most likely outcome was ordinary and manageable.', '[{"id": "f0", "type": "textarea", "label": "The situation I am worried about"}, {"id": "f1", "type": "textarea", "label": "Worst outcome and how much I believe it"}, {"id": "f2", "type": "textarea", "label": "Best outcome and how much I believe it"}, {"id": "f3", "type": "textarea", "label": "Most likely outcome and how much I believe it"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "What I take from the comparison"}]'::jsonb, array['predictions', 'catastrophizing', 'experiments']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('thought-distance-exercise', 'Thought Distance Exercise', 'cbt'::resource_kind, 'A page of steps for stepping back from a thought by changing how it is worded and viewed.', 'Use it to help a client treat a thought as a mental event, not a fact.', array['Adults']::text[], '20 minutes', 'Walk the client through rewording the thought as ''I am having the thought that...'' and then picturing it from farther away. Ask what changes. This works best on one specific thought, not a whole worry theme.', '[{"id": "f0", "type": "textarea", "label": "The thought, written as it comes"}, {"id": "f1", "type": "textarea", "label": "The thought reworded with ''I am having the thought that''"}, {"id": "f2", "type": "textarea", "label": "How strongly I believe it now"}, {"id": "f3", "type": "textarea", "label": "What I notice with more distance"}, {"id": "f4", "type": "textarea", "label": "What I want to do next"}]'::jsonb, array['cognitive fusion', 'metacognition', 'automatic thoughts']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('belief-test-planning-page', 'Belief Test Planning Page', 'cbt'::resource_kind, 'A planning sheet to test one belief through a small, specific action and record what happens.', 'Use it to help a client turn a belief into something they can test.', array['Adults']::text[], '30 minutes', 'Choose a belief the client holds firmly and a test small enough to carry out this week. Agree on what they predict and how they will know. Debrief the result with the client''s own words and avoid steering toward a lesson.', '[{"id": "f0", "type": "textarea", "label": "The belief I want to test"}, {"id": "f1", "type": "textarea", "label": "My prediction and how sure I am"}, {"id": "f2", "type": "textarea", "label": "The experiment: what, where, when"}, {"id": "f3", "type": "textarea", "label": "What I will watch for"}, {"id": "f4", "type": "textarea", "label": "What happened"}, {"id": "f5", "type": "textarea", "label": "What this tells me about the belief"}]'::jsonb, array['behavioral experiment', 'belief change', 'experiments']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('mood-lifters-menu', 'Mood Lifters Menu', 'cbt'::resource_kind, 'A menu of small activities sorted by effort, with a column for the mood before and after.', 'Use it to help a client link small actions with shifts in mood.', array['Adults']::text[], 'One week', 'Build the menu with the client from their own interests, sorted into tiny, easy and bigger. Ask them to rate mood before and after. Review the ratings with curiosity about which actions helped, and drop any that felt like chores.', '[{"id": "f0", "type": "textarea", "label": "Tiny actions I could do in five minutes"}, {"id": "f1", "type": "textarea", "label": "Easy actions I could do in an hour"}, {"id": "f2", "type": "textarea", "label": "Bigger actions I could plan for the weekend"}, {"id": "f3", "type": "textarea", "label": "Mood before and after what I tried"}, {"id": "f4", "type": "textarea", "label": "What I want more of"}]'::jsonb, array['behavioral activation', 'mood', 'activity scheduling']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('bus-passengers-role-walkthrough', 'Bus Passengers Role Walkthrough', 'act'::resource_kind, 'A walk-through of the passengers-on-the-bus metaphor with a client''s own difficult thoughts as passengers.', 'Use it to help a client keep driving toward their values with noisy thoughts aboard.', array['Adults']::text[], '30 minutes', 'Have the client name the loudest passengers and the direction they want to drive. Act out the metaphor if the client is willing. The point is that passengers can shout while the client still steers, not that they must quiet down.', '[{"id": "f0", "type": "textarea", "label": "The direction I want to drive my life"}, {"id": "f1", "type": "textarea", "label": "The passengers that shout the loudest"}, {"id": "f2", "type": "textarea", "label": "What they tell me to do"}, {"id": "f3", "type": "textarea", "label": "What I can do while they keep talking"}, {"id": "f4", "type": "textarea", "label": "One turn I will make this week"}]'::jsonb, array['metaphor', 'values', 'defusion']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('values-and-actions-gap-review', 'Values and Actions Gap Review', 'act'::resource_kind, 'A table comparing how much a value matters with how much time the client gave it this week.', 'Use it to help a client find where their days and values drift apart.', array['Adults']::text[], '25 minutes', 'Choose three or four values and ask for honest ratings of importance and recent action. A gap is information, not failure. Pick the one the client cares most about and plan a very small action toward it.', '[{"id": "f0", "type": "textarea", "label": "Value one and my action this week"}, {"id": "f1", "type": "textarea", "label": "Value two and my action this week"}, {"id": "f2", "type": "textarea", "label": "Value three and my action this week"}, {"id": "f3", "type": "textarea", "label": "The biggest gap I notice"}, {"id": "f4", "type": "textarea", "label": "A small step I will take"}]'::jsonb, array['values', 'committed action', 'review']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('hands-as-thoughts-defusion-demo', 'Hands as Thoughts Defusion Demo', 'act'::resource_kind, 'An in-session demo where the client holds their hands over their face, then lowers them to see the room.', 'Use it to give a client a felt sense of thoughts getting in the way of seeing.', array['Adults']::text[], '15 minutes', 'Ask the client to cover their face with their hands as if they were thoughts, notice what they can do, then lower the hands slowly. Ask what changed. It is a short demo and should be followed by a short talk about what thoughts do and do not do.', '[{"id": "f0", "type": "textarea", "label": "What it was like with hands over my face"}, {"id": "f1", "type": "textarea", "label": "What it was like with hands in my lap"}, {"id": "f2", "type": "textarea", "label": "A thought that sits like my hands do"}, {"id": "f3", "type": "textarea", "label": "What I could do while the thought is near"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['defusion', 'metaphor', 'experiential']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('willingness-rating-sheet', 'Willingness Rating Sheet', 'act'::resource_kind, 'A rating page for how willing a client is to feel the discomfort that comes with a valued action.', 'Use it to help a client choose how much discomfort they will carry toward something that matters.', array['Adults']::text[], '20 minutes', 'Ask for the valued action and the discomfort that comes with it, then a willingness rating from zero to ten. Explore what a slightly higher number would take. Respect a low number and ask what would make a smaller action possible.', '[{"id": "f0", "type": "textarea", "label": "The action that matters to me"}, {"id": "f1", "type": "textarea", "label": "The discomfort that comes with it"}, {"id": "f2", "type": "textarea", "label": "My willingness from 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What would make it a point higher"}, {"id": "f4", "type": "textarea", "label": "What I will try this week"}]'::jsonb, array['willingness', 'values', 'committed action']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('present-moment-anchors-card', 'Present Moment Anchors Card', 'act'::resource_kind, 'A pocket card for noticing five things in the room and returning attention to what the client is doing.', 'Use it to help a client come back to the present during a busy day.', array['Adults']::text[], 'Five minutes daily', 'Practice the anchors in session first so the card is familiar. Clients can write their own anchors, such as a sound or the feel of the chair. Keep it short and treat wandering attention as the normal reason to practice.', '[{"id": "f0", "type": "textarea", "label": "Five things I can see"}, {"id": "f1", "type": "textarea", "label": "Three sounds I can hear"}, {"id": "f2", "type": "textarea", "label": "One thing I can feel under my hands"}, {"id": "f3", "type": "textarea", "label": "A place in my day where I will try this"}, {"id": "f4", "type": "textarea", "label": "How it felt to pause"}]'::jsonb, array['present moment', 'mindfulness', 'practice']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-urge-acting-sheet', 'Pros and Cons of Urge Acting Sheet', 'dbt'::resource_kind, 'A DBT pros-and-cons grid for acting on an urge versus using a skill, filled in during calm.', 'Use it to help a client prepare a reason to choose a skill before a strong urge.', array['Adults']::text[], '25 minutes', 'Complete the grid in a calm moment and keep it handy for hard ones. Include both short-term and long-term pros and cons. Clients often skip the short-term pros of the urge, and naming them honestly makes the sheet more believable.', '[{"id": "f0", "type": "textarea", "label": "The urge or behavior I am weighing"}, {"id": "f1", "type": "textarea", "label": "Pros of acting on it"}, {"id": "f2", "type": "textarea", "label": "Cons of acting on it"}, {"id": "f3", "type": "textarea", "label": "Pros of using a skill instead"}, {"id": "f4", "type": "textarea", "label": "Cons of using a skill"}, {"id": "f5", "type": "textarea", "label": "My choice for next time"}]'::jsonb, array['distress tolerance', 'pros and cons', 'DBT skills']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('describe-and-label-emotions-worksheet', 'Describe and Label Emotions Worksheet', 'dbt'::resource_kind, 'A worksheet for naming an emotion by its prompt, body cues, urges and aftermath.', 'Use it to help a client describe an emotion in full without acting on it.', array['Adults']::text[], '25 minutes', 'Take one recent emotion and walk through the prompting event, interpretation, body sensations, urge and what followed. Ask the client to stick to what an observer could see, then separate the story from the facts.', '[{"id": "f0", "type": "textarea", "label": "What happened just before"}, {"id": "f1", "type": "textarea", "label": "What I told myself about it"}, {"id": "f2", "type": "textarea", "label": "What I felt in my body"}, {"id": "f3", "type": "textarea", "label": "What I wanted to do"}, {"id": "f4", "type": "textarea", "label": "What I did and what followed"}]'::jsonb, array['emotion regulation', 'observe and describe', 'core DBT']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('open-palms-posture-practice', 'Open Palms Posture Practice', 'dbt'::resource_kind, 'A short practice for relaxing the body toward acceptance, with space to note what shifts.', 'Use it to help a client soften toward a situation they cannot change right now.', array['Adults']::text[], 'Five minutes', 'Teach the posture in session: palms open, shoulders loose, a half-smile if it comes. Pair it with a single hard situation and ask for a note on what changes. It is a body cue for acceptance and does not mean the client approves.', '[{"id": "f0", "type": "textarea", "label": "The situation I am fighting"}, {"id": "f1", "type": "textarea", "label": "What my body does when I resist"}, {"id": "f2", "type": "textarea", "label": "What I notice with open hands"}, {"id": "f3", "type": "textarea", "label": "A sentence I can say to myself"}, {"id": "f4", "type": "textarea", "label": "When I will practice this"}]'::jsonb, array['radical acceptance', 'distress tolerance', 'willingness']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('interpersonal-priorities-rating', 'Interpersonal Priorities Rating', 'dbt'::resource_kind, 'A rating sheet that helps a client weigh the goal, the relationship and self-respect in a request.', 'Use it to help a client pick how firmly to ask in a situation.', array['Adults']::text[], '20 minutes', 'Walk through the three priorities with a real request and have the client rate each from one to ten. Then decide together whether to lean on DEAR MAN, GIVE or FAST more heavily. Different ratings lead to different approaches.', '[{"id": "f0", "type": "textarea", "label": "What I want from this situation"}, {"id": "f1", "type": "textarea", "label": "How important the goal is, 1 to 10"}, {"id": "f2", "type": "textarea", "label": "How important the relationship is, 1 to 10"}, {"id": "f3", "type": "textarea", "label": "How important my self-respect is, 1 to 10"}, {"id": "f4", "type": "textarea", "label": "The approach I will take"}]'::jsonb, array['interpersonal effectiveness', 'DEAR MAN', 'priorities']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('daily-wise-mind-check-in', 'Daily Wise Mind Check-In', 'dbt'::resource_kind, 'A brief daily check-in to notice emotion mind, reasonable mind and what wise mind says.', 'Use it to help a client practice reaching for wise mind each day.', array['Adults']::text[], 'Five minutes daily', 'Ask for one entry a day tied to a small decision. Look in session for where the client already finds wise mind and where they overlook it. Keep entries short so the habit sticks.', '[{"id": "f0", "type": "textarea", "label": "The situation today"}, {"id": "f1", "type": "textarea", "label": "What emotion mind says"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says"}, {"id": "f3", "type": "textarea", "label": "What wise mind says"}, {"id": "f4", "type": "textarea", "label": "What I did"}]'::jsonb, array['wise mind', 'core DBT', 'daily reflection']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('weekly-state-of-us-meeting-agenda', 'Weekly State of Us Meeting Agenda', 'couples'::resource_kind, 'A shared agenda for a short weekly talk covering appreciation, chores, concerns and plans.', 'Use it to give a couple a steady, low-pressure time to talk about the relationship.', array['Couples']::text[], '30 minutes weekly', 'Each partner fills in their own column beforehand and brings it. Start with appreciation, end with something to look forward to, and keep concerns to one each. Model it in session before they try it at home.', '[{"id": "f0", "type": "textarea", "label": "Partner A: one thing I appreciated this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: one thing I appreciated this week"}, {"id": "f2", "type": "textarea", "label": "Partner A: one concern, said gently"}, {"id": "f3", "type": "textarea", "label": "Partner B: one concern, said gently"}, {"id": "f4", "type": "textarea", "label": "Something we will plan together"}]'::jsonb, array['Gottman', 'communication', 'weekly review']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('repair-attempt-phrase-bank', 'Repair Attempt Phrase Bank', 'couples'::resource_kind, 'Each partner lists phrases that help them reconnect after a hard exchange.', 'Use it to help a couple agree on repair words that actually land.', array['Couples']::text[], '20 minutes', 'Have each partner write phrases that would help them soften, then trade lists. Ask what they would actually say in the heat of it. Pick two phrases each to try and review in the next session how they were received.', '[{"id": "f0", "type": "textarea", "label": "Partner A: words that help me soften"}, {"id": "f1", "type": "textarea", "label": "Partner B: words that help me soften"}, {"id": "f2", "type": "textarea", "label": "Words that would make it worse"}, {"id": "f3", "type": "textarea", "label": "Two phrases we will each try"}, {"id": "f4", "type": "textarea", "label": "How we will let each other know it worked"}]'::jsonb, array['repair', 'Gottman', 'communication']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('planning-load-balance-check', 'Planning Load Balance Check', 'couples'::resource_kind, 'A planning sheet for comparing each partner''s commitments and who carries the logistics.', 'Use it to help a couple see and rebalance the invisible planning work.', array['Couples']::text[], '30 minutes', 'Have each partner list recurring tasks and who plans, remembers and does them. Many couples find that planning is the uneven part. Stay neutral and help them choose one task to hand over completely.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I plan or remember"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I plan or remember"}, {"id": "f2", "type": "textarea", "label": "Where it feels uneven"}, {"id": "f3", "type": "textarea", "label": "One task we will hand over completely"}, {"id": "f4", "type": "textarea", "label": "When we will check in again"}]'::jsonb, array['mental load', 'fairness', 'roles']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('appreciation-jar-cards', 'Appreciation Jar Cards', 'couples'::resource_kind, 'A set of cards where partners write short notes on what they valued about each other this week.', 'Use it to help a couple notice and say the good they otherwise let pass.', array['Couples']::text[], 'Ten minutes daily', 'Ask the couple to write one card each a day and read them aloud at the weekend. Specific notes work better than general ones. If one partner feels awkward, start with two a week and build from there.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something B did that I valued"}, {"id": "f1", "type": "textarea", "label": "Partner B: something A did that I valued"}, {"id": "f2", "type": "textarea", "label": "A small moment we shared this week"}, {"id": "f3", "type": "textarea", "label": "A thank-you I have not said yet"}, {"id": "f4", "type": "textarea", "label": "What it was like to hear the notes"}]'::jsonb, array['appreciation', 'fondness', 'connection']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('different-needs-translation-sheet', 'Different Needs Translation Sheet', 'couples'::resource_kind, 'Partners write what they asked for, what they needed underneath, and what they could ask instead.', 'Use it to help a couple move from complaint to a clear request.', array['Couples']::text[], '25 minutes', 'Take one recurring complaint and have each partner translate it into a need and a doable request. Practice stating the request in one calm sentence. Watch for requests hidden inside criticism and name them kindly.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my complaint"}, {"id": "f1", "type": "textarea", "label": "Partner A: the need under it"}, {"id": "f2", "type": "textarea", "label": "Partner B: my complaint"}, {"id": "f3", "type": "textarea", "label": "Partner B: the need under it"}, {"id": "f4", "type": "textarea", "label": "A request each of us can make"}]'::jsonb, array['needs', 'communication', 'couples']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('feelings-weather-station', 'Feelings Weather Station', 'kids'::resource_kind, 'A child draws today''s feelings as weather and builds a small forecast with a parent.', 'Use it to help a child name feelings through a picture they can share.', array['Children']::text[], '20 minutes', 'The child draws sun, clouds or storms for how they feel and gives a forecast for tomorrow. The parent listens, repeats back what they see, and does not fix. Post the drawing where the child can add a new one each day.', '[{"id": "f0", "type": "textarea", "label": "Today my feelings are like this weather"}, {"id": "f1", "type": "textarea", "label": "What made the weather change"}, {"id": "f2", "type": "textarea", "label": "What helps a storm pass"}, {"id": "f3", "type": "textarea", "label": "My forecast for tomorrow"}]'::jsonb, array['emotion recognition', 'children', 'art']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('settling-glitter-jar-craft', 'Settling Glitter Jar Craft', 'kids'::resource_kind, 'A child makes a glitter jar with a parent and learns to watch it settle while breathing slowly.', 'Use it to give a child a visual, hands-on way to slow down.', array['Children']::text[], '30 minutes', 'Make the jar together with water, glue and glitter, sealed tightly. Explain that the glitter settles like busy thoughts and shake it only when the child chooses. The parent practices with the child at calm times, not only upsets.', '[{"id": "f0", "type": "textarea", "label": "Colors I picked and why"}, {"id": "f1", "type": "textarea", "label": "What it looks like when I am upset"}, {"id": "f2", "type": "textarea", "label": "How the jar looks when it settles"}, {"id": "f3", "type": "textarea", "label": "Where we will keep the jar"}]'::jsonb, array['calming', 'craft', 'children']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('brave-steps-ladder-drawing', 'Brave Steps Ladder Drawing', 'kids'::resource_kind, 'A child draws a staircase and places small brave steps on each stair with stickers.', 'Use it to help a child plan small steps toward something hard.', array['Children']::text[], '30 minutes', 'The child draws the staircase and picks something they want to do, then you and the parent break it into small steps. The parent cheers effort and does not push past the step. Add stickers as each stair is tried.', '[{"id": "f0", "type": "textarea", "label": "The big brave thing I want to do"}, {"id": "f1", "type": "textarea", "label": "First tiny step at the bottom"}, {"id": "f2", "type": "textarea", "label": "Next step up"}, {"id": "f3", "type": "textarea", "label": "The top stair"}, {"id": "f4", "type": "textarea", "label": "Who will cheer me on"}]'::jsonb, array['exposure', 'approach', 'children']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('kindness-tree-collage', 'Kindness Tree Collage', 'kids'::resource_kind, 'A child builds a paper tree and adds a leaf each time they notice or give kindness.', 'Use it to help a child notice kind things they and others do.', array['Children']::text[], 'One week', 'The child cuts out a trunk and adds a leaf with a short note each day. The parent writes the words for younger children. At the end of the week, count the leaves together and talk about which one felt best.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did"}, {"id": "f1", "type": "textarea", "label": "A kind thing someone did for me"}, {"id": "f2", "type": "textarea", "label": "How it felt"}, {"id": "f3", "type": "textarea", "label": "A leaf I want to add tomorrow"}]'::jsonb, array['kindness', 'craft', 'children']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('worry-monster-feeding-box', 'Worry Monster Feeding Box', 'kids'::resource_kind, 'A child decorates a box for worries, writes or draws them, and feeds the monster at a set time.', 'Use it to give a child a place to put worries and a time to let them go.', array['Children']::text[], '30 minutes', 'The child decorates the box and picks a time of day to feed it. Worries go in, and the parent does not rescue or lecture, only listens briefly. Check the contents with the child once a week and decide what to do with each.', '[{"id": "f0", "type": "textarea", "label": "What my worry monster looks like"}, {"id": "f1", "type": "textarea", "label": "A worry I fed it today"}, {"id": "f2", "type": "textarea", "label": "What the monster says back"}, {"id": "f3", "type": "textarea", "label": "What I do while it eats"}, {"id": "f4", "type": "textarea", "label": "What I want to tell it"}]'::jsonb, array['worry', 'children', 'externalizing']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('two-truths-and-a-wish-feelings-round', 'Two Truths and a Wish Feelings Round', 'game'::resource_kind, 'Players share two true things and one wish about a recent feeling, and others guess the wish.', 'Use it to help a group share feelings through a light, familiar format.', array['Teens', 'Groups']::text[], '20 minutes', 'Each player offers two true things and one wish about their week. Others guess the wish, then the speaker reveals it. Debrief on what it was like to share and to be guessed. Keep the pace light and let anyone pass.', '[{"id": "f0", "type": "textarea", "label": "My two true things"}, {"id": "f1", "type": "textarea", "label": "My wish"}, {"id": "f2", "type": "textarea", "label": "What I learned about someone else"}, {"id": "f3", "type": "textarea", "label": "What it was like to share"}]'::jsonb, array['game', 'connection', 'icebreaker']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('skill-charades', 'Skill Charades', 'game'::resource_kind, 'Players act out a coping skill without words while others guess it, then say when they might use it.', 'Use it to help a group remember coping skills through movement and laughter.', array['Teens', 'Groups']::text[], '25 minutes', 'Write skills on cards such as breathing, grounding, asking for help and taking a break. Players take turns acting them out. After each guess, the actor says when they could use it. Debrief on which skill felt most doable.', '[{"id": "f0", "type": "textarea", "label": "Skills I acted or guessed"}, {"id": "f1", "type": "textarea", "label": "A skill I forgot I had"}, {"id": "f2", "type": "textarea", "label": "A moment this week I could use one"}, {"id": "f3", "type": "textarea", "label": "The skill I will try first"}]'::jsonb, array['game', 'coping skills', 'skills']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('pass-the-compliment-circle', 'Pass the Compliment Circle', 'game'::resource_kind, 'Players pass a ball and give the next person a specific, true compliment about what they do.', 'Use it to help a group practice giving and receiving kind words.', array['Teens', 'Groups']::text[], '20 minutes', 'Sit in a circle and pass a soft ball. The holder gives a specific compliment about an action, not looks. The receiver says thank you without deflecting. Debrief on how it felt to receive and what made some compliments land.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave"}, {"id": "f1", "type": "textarea", "label": "A compliment I received"}, {"id": "f2", "type": "textarea", "label": "What it was like to say thank you"}, {"id": "f3", "type": "textarea", "label": "A compliment I want to give this week"}]'::jsonb, array['game', 'appreciation', 'group']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('options-brainstorm-relay', 'Options Brainstorm Relay', 'game'::resource_kind, 'Teams race to brainstorm solutions to a card-based problem and then pick one together.', 'Use it to help a group practice generating options before choosing.', array['Teens', 'Groups']::text[], '30 minutes', 'Teams get a problem card and a minute to list ideas, with no judging. They then pick one and say why. Debrief on how it felt to hold off judgment and on which options surprised them. Use client-made problem cards if they are willing.', '[{"id": "f0", "type": "textarea", "label": "Our problem card"}, {"id": "f1", "type": "textarea", "label": "Ideas we listed"}, {"id": "f2", "type": "textarea", "label": "The idea we chose and why"}, {"id": "f3", "type": "textarea", "label": "What I learned about options"}]'::jsonb, array['game', 'problem solving', 'group']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('mindful-minute-challenge', 'Mindful Minute Challenge', 'game'::resource_kind, 'Players try to stay focused on one simple object for a minute and compare what they noticed.', 'Use it to help a group practice attention in a playful, low-stakes way.', array['Teens', 'Groups']::text[], '15 minutes', 'Hand each player an object such as a stone or a leaf. For one minute, they notice everything about it. Compare notes. Wandering is expected and counts as part of the game. Debrief on what pulled attention away and how they came back.', '[{"id": "f0", "type": "textarea", "label": "What I noticed about my object"}, {"id": "f1", "type": "textarea", "label": "What pulled my attention away"}, {"id": "f2", "type": "textarea", "label": "How I came back"}, {"id": "f3", "type": "textarea", "label": "Where I could try this in daily life"}]'::jsonb, array['game', 'mindfulness', 'attention']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('safe-cues-inventory', 'Safe Cues Inventory', 'worksheet'::resource_kind, 'A sheet for listing places, people and objects that feel safe, with senses for each.', 'Use it to help a client build a store of safety cues for grounding.', array['Adults']::text[], '25 minutes', 'This stays on the present and on what feels safe now. Invite the client to include real and imagined places and note the senses involved. Do not ask for details of past events. Pace the session and stop if the client feels pulled out of the present.', '[{"id": "f0", "type": "textarea", "label": "A place that feels safe, real or imagined"}, {"id": "f1", "type": "textarea", "label": "What I see, hear and feel there"}, {"id": "f2", "type": "textarea", "label": "A person or pet who helps me feel safe"}, {"id": "f3", "type": "textarea", "label": "An object I can hold when I need steadiness"}, {"id": "f4", "type": "textarea", "label": "How I can bring one of these into my day"}]'::jsonb, array['grounding', 'safety', 'stabilizing', 'PTSD and trauma']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('stuck-point-notes-for-today', 'Stuck Point Notes for Today', 'cbt'::resource_kind, 'A short log that lets a client name a current belief that feels stuck and look at it with support.', 'Use it to help a client notice stuck beliefs about safety or trust without retelling events.', array['Adults']::text[], '25 minutes', 'Keep the focus on the belief as it shows up today, such as ''I can''t trust anyone''. Ask what supports it and what a more balanced version might be. Do not ask for the story behind it as homework; work with the thought only.', '[{"id": "f0", "type": "textarea", "label": "A belief that keeps showing up"}, {"id": "f1", "type": "textarea", "label": "How much I believe it right now"}, {"id": "f2", "type": "textarea", "label": "What supports it"}, {"id": "f3", "type": "textarea", "label": "What does not fit it"}, {"id": "f4", "type": "textarea", "label": "A more balanced way to say it"}]'::jsonb, array['PTSD and trauma', 'cognitive restructuring', 'stabilizing']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('anchoring-skills-ladder', 'Anchoring Skills Ladder', 'dbt'::resource_kind, 'A ladder of distress tolerance skills ordered from lightest to strongest for intense moments.', 'Use it to help a client choose a grounding skill that fits the strength of the moment.', array['Adults']::text[], '30 minutes', 'Build the ladder with the client in a calm moment, from noticing five things to cold water or movement. Rehearse the top rung only if the client agrees and the setting is safe. Keep a copy where it is easy to reach.', '[{"id": "f0", "type": "textarea", "label": "Light skills I can use when a wave is small"}, {"id": "f1", "type": "textarea", "label": "Medium skills for when it builds"}, {"id": "f2", "type": "textarea", "label": "Strong skills for the hardest moments"}, {"id": "f3", "type": "textarea", "label": "Who I can contact for support"}, {"id": "f4", "type": "textarea", "label": "Which rung I will rehearse this week"}]'::jsonb, array['distress tolerance', 'TIPP', 'grounding', 'PTSD and trauma']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('present-and-safe-reminder-cards', 'Present and Safe Reminder Cards', 'act'::resource_kind, 'Cards a client writes with true statements about the present and a value they are moving toward.', 'Use it to help a client return to the present and to what they care about.', array['Adults']::text[], '20 minutes', 'Write cards in the session such as ''Right now I am here and I am safe in this room'' only if the client finds them true. Pair each with a value-based action. Review which cards help and drop any that feel forced.', '[{"id": "f0", "type": "textarea", "label": "A true sentence about this moment"}, {"id": "f1", "type": "textarea", "label": "A value that matters to me"}, {"id": "f2", "type": "textarea", "label": "A small action toward that value"}, {"id": "f3", "type": "textarea", "label": "Where I will keep these cards"}, {"id": "f4", "type": "textarea", "label": "How I will know the cards are helping"}]'::jsonb, array['PTSD and trauma', 'present moment', 'values']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('grounding-scavenger-hunt', 'Grounding Scavenger Hunt', 'game'::resource_kind, 'A paced game where players find objects by color, texture and sound to anchor in the present.', 'Use it to help clients practice grounding through a light and structured game.', array['Teens', 'Groups']::text[], '20 minutes', 'Call out categories such as something soft, something blue or a sound you can hear. Players find or name one. Keep to the present and never ask about past events. Debrief on which category settled them most and stop whenever someone needs a break.', '[{"id": "f0", "type": "textarea", "label": "The category that helped me most"}, {"id": "f1", "type": "textarea", "label": "Something soft I found"}, {"id": "f2", "type": "textarea", "label": "A sound I noticed"}, {"id": "f3", "type": "textarea", "label": "How my body feels now"}, {"id": "f4", "type": "textarea", "label": "When I could use this at home"}]'::jsonb, array['PTSD and trauma', 'game', 'grounding']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('worry-window-planner', 'Worry Window Planner', 'worksheet'::resource_kind, 'A weekly page for scheduling a short worry time and parking worries until then.', 'Use it to help a client contain worry to a set window.', array['Adults']::text[], 'One week', 'Agree on a daily fifteen-minute window and a place to jot worries during the day. In worry time, sort each worry into one that can be acted on and one that cannot. Review in session how many were left and what changed.', '[{"id": "f0", "type": "textarea", "label": "My worry time each day"}, {"id": "f1", "type": "textarea", "label": "Worries I parked today"}, {"id": "f2", "type": "textarea", "label": "Worries I can act on, and the first step"}, {"id": "f3", "type": "textarea", "label": "Worries I cannot act on, and what I will do instead"}, {"id": "f4", "type": "textarea", "label": "What I noticed after a week"}]'::jsonb, array['anxiety', 'worry', 'scheduling']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('what-if-then-what-chain', 'What If Then What Chain', 'cbt'::resource_kind, 'A chain that follows a ''what if'' worry forward to the next steps the client could take.', 'Use it to help a client move from a catastrophic question to a coping plan.', array['Adults']::text[], '25 minutes', 'Write the worry, then ask ''and then what?'' until the client reaches a point they could cope with or act on. Notice where the chain stops being likely. End with one thing they would do if it came true.', '[{"id": "f0", "type": "textarea", "label": "My ''what if'' worry"}, {"id": "f1", "type": "textarea", "label": "And then what happens?"}, {"id": "f2", "type": "textarea", "label": "And then what?"}, {"id": "f3", "type": "textarea", "label": "How likely each step is, 0 to 100"}, {"id": "f4", "type": "textarea", "label": "What I would do if it happened"}, {"id": "f5", "type": "textarea", "label": "What I want to remember"}]'::jsonb, array['anxiety', 'catastrophizing', 'cope ahead']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('anxiety-as-weather-practice', 'Anxiety as Weather Practice', 'act'::resource_kind, 'A practice for watching anxious feelings like weather while taking a valued action.', 'Use it to help a client carry anxious feelings without waiting for them to leave.', array['Adults']::text[], '25 minutes', 'Name the feelings as weather passing overhead and ask the client to keep going with a valued task. Ask what it was like to let the weather be. The point is the action, and weather changing is a bonus, not the goal.', '[{"id": "f0", "type": "textarea", "label": "The weather in me right now"}, {"id": "f1", "type": "textarea", "label": "A valued action I want to take"}, {"id": "f2", "type": "textarea", "label": "What I did while the weather stayed"}, {"id": "f3", "type": "textarea", "label": "What I noticed when I stopped fighting it"}, {"id": "f4", "type": "textarea", "label": "What I will try again"}]'::jsonb, array['anxiety', 'acceptance', 'metaphor']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('worry-dragon-drawing', 'Worry Dragon Drawing', 'kids'::resource_kind, 'A child draws a worry dragon, gives it a name and decides how to politely tell it to wait.', 'Use it to help a child step back from worries by giving them a shape.', array['Children']::text[], '25 minutes', 'The child draws the dragon and writes what it says. The parent listens, then helps the child try a line such as ''Thanks, dragon, I''ll check later''. Avoid lengthy reassurance; short, calm replies work better.', '[{"id": "f0", "type": "textarea", "label": "My dragon looks like this"}, {"id": "f1", "type": "textarea", "label": "What my dragon says"}, {"id": "f2", "type": "textarea", "label": "What I say back"}, {"id": "f3", "type": "textarea", "label": "What I do while the dragon is loud"}, {"id": "f4", "type": "textarea", "label": "Who helps me"}]'::jsonb, array['worry', 'externalizing', 'children', 'anxiety']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('partner-support-plan-for-anxious-moments', 'Partner Support Plan for Anxious Moments', 'couples'::resource_kind, 'Partners agree on how to help when anxiety is high, what helps and what does not.', 'Use it to help a couple settle on a supportive response to anxiety.', array['Couples']::text[], '30 minutes', 'Have the anxious partner say what helps and what feels like pressure, and the other say what they can offer. Watch for reassurance that keeps worry going. End with one agreed phrase and one agreed action.', '[{"id": "f0", "type": "textarea", "label": "Partner A: when anxiety is high, I need"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can offer"}, {"id": "f3", "type": "textarea", "label": "A phrase we will use"}, {"id": "f4", "type": "textarea", "label": "How we will review this"}]'::jsonb, array['anxiety', 'support', 'couples']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('small-wins-record', 'Small Wins Record', 'worksheet'::resource_kind, 'A daily record of tiny things done, however small, with a short note about how each felt.', 'Use it to help a client notice what they are doing when everything feels like too much.', array['Adults']::text[], 'One week', 'Define a win generously: getting out of bed, a shower, a short reply. Ask for three a day. Review the list together without adding pressure, and look at which wins gave a little lift.', '[{"id": "f0", "type": "textarea", "label": "Three small things I did today"}, {"id": "f1", "type": "textarea", "label": "Which one felt best"}, {"id": "f2", "type": "textarea", "label": "What made it possible"}, {"id": "f3", "type": "textarea", "label": "One tiny thing for tomorrow"}, {"id": "f4", "type": "textarea", "label": "If my mood feels unsafe, I can call or text 988"}]'::jsonb, array['low mood', 'behavioral activation', 'mood tracking', 'depression']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('evidence-for-the-quiet-voice', 'Evidence for the Quiet Voice', 'cbt'::resource_kind, 'A thought record for the harsh inner voice, with a column for kinder, accurate replies.', 'Use it to help a client check a harsh thought and write a fairer one.', array['Adults']::text[], '25 minutes', 'Choose one harsh thought from the week and run the evidence for and against it. Ask what they would say to a friend. Keep the new thought believable; a small shift is better than a forced positive.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The harsh thought"}, {"id": "f2", "type": "textarea", "label": "Evidence for it"}, {"id": "f3", "type": "textarea", "label": "Evidence against it"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f5", "type": "textarea", "label": "A fairer thought"}]'::jsonb, array['depression', 'thought record', 'self-criticism']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('values-in-low-energy-days', 'Values in Low Energy Days', 'act'::resource_kind, 'A menu of values-based actions sized to low, medium and higher energy.', 'Use it to help a client keep acting on values when energy is low.', array['Adults']::text[], '25 minutes', 'Draw three columns for energy and fill each with actions linked to values, such as texting a friend or watering a plant. Ask the client to pick by the day''s energy, not by guilt. Revisit which items are realistic.', '[{"id": "f0", "type": "textarea", "label": "A value I care about"}, {"id": "f1", "type": "textarea", "label": "A tiny action when energy is low"}, {"id": "f2", "type": "textarea", "label": "An action when energy is medium"}, {"id": "f3", "type": "textarea", "label": "An action when energy is higher"}, {"id": "f4", "type": "textarea", "label": "Which one I will do today"}]'::jsonb, array['low mood', 'values', 'committed action', 'depression']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('build-mastery-and-pleasant-events-plan', 'Build Mastery and Pleasant Events Plan', 'dbt'::resource_kind, 'A weekly plan with one mastery action and one pleasant event each day.', 'Use it to help a client balance accomplishment with enjoyment.', array['Adults']::text[], 'One week', 'Choose one mastery action and one pleasant event per day, both small enough to be done on a hard day. Review whether they happened and how they felt. Adjust difficulty up or down based on the week.', '[{"id": "f0", "type": "textarea", "label": "Mastery action I will do each day"}, {"id": "f1", "type": "textarea", "label": "Pleasant event I will do each day"}, {"id": "f2", "type": "textarea", "label": "What got in the way"}, {"id": "f3", "type": "textarea", "label": "How I felt afterward"}, {"id": "f4", "type": "textarea", "label": "What I will change next week"}]'::jsonb, array['building mastery', 'pleasant events', 'DBT skills', 'depression']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('low-mood-and-closeness-conversation', 'Low Mood and Closeness Conversation', 'couples'::resource_kind, 'Partners talk about what low mood is like and how to stay connected without pressure.', 'Use it to help a couple talk about low mood without blame.', array['Couples']::text[], '30 minutes', 'Invite the person with low mood to say what they would like from their partner on hard days, and the partner to share what they need too. Avoid problem-solving too early. Agree on one small way to connect each day.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what low days feel like to me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I notice and feel"}, {"id": "f2", "type": "textarea", "label": "What helps us stay close"}, {"id": "f3", "type": "textarea", "label": "What we need from each other"}, {"id": "f4", "type": "textarea", "label": "One small daily connection"}]'::jsonb, array['low mood', 'connection', 'couples', 'depression']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('task-launch-pad', 'Task Launch Pad', 'worksheet'::resource_kind, 'A sheet that breaks a dreaded task into a first two-minute step, a timer and a reward.', 'Use it to help a client start a task that feels hard to begin.', array['Adults']::text[], '20 minutes', 'Pick one task the client has been avoiding and shrink the first step until it is almost silly. Add a timer and a small reward afterward. Review whether starting got easier and what made it so.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "The two-minute first step"}, {"id": "f2", "type": "textarea", "label": "How long I will set the timer for"}, {"id": "f3", "type": "textarea", "label": "My reward when I start"}, {"id": "f4", "type": "textarea", "label": "What got in the way"}]'::jsonb, array['ADHD', 'task initiation', 'executive skills']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('time-blindness-estimator', 'Time Blindness Estimator', 'cbt'::resource_kind, 'A log comparing estimated and actual task time to calibrate planning.', 'Use it to help a client plan with more realistic time estimates.', array['Adults']::text[], 'One week', 'Ask the client to guess task times, then record real times for a week. Look at the gap and add a buffer. Many clients find the gap steady, which makes planning easier. Avoid judgment about speed.', '[{"id": "f0", "type": "textarea", "label": "The task"}, {"id": "f1", "type": "textarea", "label": "My time guess"}, {"id": "f2", "type": "textarea", "label": "How long it really took"}, {"id": "f3", "type": "textarea", "label": "The gap"}, {"id": "f4", "type": "textarea", "label": "The buffer I will add next time"}]'::jsonb, array['ADHD', 'time management', 'planning']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('body-doubling-craft-table', 'Body Doubling Craft Table', 'kids'::resource_kind, 'A child and parent work side by side on their own tasks with a visual timer and a stamp card.', 'Use it to help a child get through a task with someone nearby.', array['Children']::text[], '30 minutes', 'The parent sits with the child at a table, each with their own task, and sets a visual timer. A stamp goes on the card after each round. Keep rounds short and praise starting, not only finishing.', '[{"id": "f0", "type": "textarea", "label": "The task I am working on"}, {"id": "f1", "type": "textarea", "label": "How long I will work"}, {"id": "f2", "type": "textarea", "label": "How I felt when the timer ended"}, {"id": "f3", "type": "textarea", "label": "What helped me stay going"}, {"id": "f4", "type": "textarea", "label": "What I will do for a break"}]'::jsonb, array['ADHD', 'children', 'executive skills']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('impulse-brake-freeze-game', 'Impulse Brake Freeze Game', 'game'::resource_kind, 'Players move to music and freeze on a signal, then name the pause and what they chose next.', 'Use it to help clients practice noticing and holding a pause.', array['Teens', 'Groups']::text[], '20 minutes', 'Play music and call freeze. Players hold still and name something they notice, then choose a new action. Vary the signal so it is not predictable. Debrief on the pause, what it took, and where in real life it could help.', '[{"id": "f0", "type": "textarea", "label": "What I noticed while frozen"}, {"id": "f1", "type": "textarea", "label": "What was hardest about the pause"}, {"id": "f2", "type": "textarea", "label": "A moment this week I could pause"}, {"id": "f3", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['ADHD', 'impulse control', 'game']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('household-systems-reset', 'Household Systems Reset', 'couples'::resource_kind, 'Partners build one shared system for a recurring chore, with reminders that don''t feel like nagging.', 'Use it to help a couple replace reminders with a shared system.', array['Couples']::text[], '30 minutes', 'Choose one chore that causes friction. Agree on a visible system such as a shared list or a fixed time, and how reminders will be sent and received. Name the tone you each prefer. Revisit after two weeks.', '[{"id": "f0", "type": "textarea", "label": "The chore that causes friction"}, {"id": "f1", "type": "textarea", "label": "Partner A: how I like reminders"}, {"id": "f2", "type": "textarea", "label": "Partner B: how I like reminders"}, {"id": "f3", "type": "textarea", "label": "The system we will try"}, {"id": "f4", "type": "textarea", "label": "How we will check in"}]'::jsonb, array['ADHD', 'household', 'systems']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('urge-log-and-pattern-finder', 'Urge Log and Pattern Finder', 'worksheet'::resource_kind, 'A log of urges for substance use with time, place, trigger, intensity and what the client did.', 'Use it to help a client see patterns in urges and the choices they made.', array['Adults']::text[], 'One week', 'Ask for brief entries and stress that urges noted are not failures. Look for repeating times, places and feelings, and ask what worked even once. Pick one pattern and plan a change together.', '[{"id": "f0", "type": "textarea", "label": "When and where the urge came"}, {"id": "f1", "type": "textarea", "label": "What was going on"}, {"id": "f2", "type": "textarea", "label": "How strong it was, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "What helped, even a little"}]'::jsonb, array['addiction', 'urges', 'substance use']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('urge-thoughts-reality-check', 'Urge Thoughts Reality Check', 'cbt'::resource_kind, 'A thought record for the thoughts that come with an urge for substance use.', 'Use it to help a client examine urge thoughts like ''just once will be fine''.', array['Adults']::text[], '25 minutes', 'Write the exact thought and ask what it promises and what has really followed in the past. Build a response the client believes. Keep the stance nonjudgmental and let the client define their own goal.', '[{"id": "f0", "type": "textarea", "label": "The urge thought"}, {"id": "f1", "type": "textarea", "label": "What it promises"}, {"id": "f2", "type": "textarea", "label": "What happened last time"}, {"id": "f3", "type": "textarea", "label": "A response I believe"}, {"id": "f4", "type": "textarea", "label": "What I will do next"}]'::jsonb, array['addiction', 'urges', 'thought challenging']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('urge-surfing-with-values', 'Urge Surfing with Values', 'act'::resource_kind, 'A practice for noticing an urge rise and fall while holding a value in mind.', 'Use it to help a client ride out an urge while staying connected to what matters.', array['Adults']::text[], '20 minutes', 'Guide the client to watch the urge like a wave, noting body sensations, and to name a value as they do. Practice in session with a mild urge first. The aim is to build room between urge and action.', '[{"id": "f0", "type": "textarea", "label": "Where I feel the urge in my body"}, {"id": "f1", "type": "textarea", "label": "How it changed over a few minutes"}, {"id": "f2", "type": "textarea", "label": "A value I held in mind"}, {"id": "f3", "type": "textarea", "label": "What I did next"}, {"id": "f4", "type": "textarea", "label": "Where I will practice"}]'::jsonb, array['addiction', 'urges', 'values']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('alternate-rebellion-and-adaptive-denial-plan', 'Alternate Rebellion and Adaptive Denial Plan', 'dbt'::resource_kind, 'A plan that lists safe alternatives for urges and ways to put a decision on hold.', 'Use it to help a client prepare skills for moments when urges arise.', array['Adults']::text[], '30 minutes', 'Fill in alternative actions and ways to delay a decision, such as a timer or a call. Rehearse one in session. Add a line about who to contact for support. Substance use and urges are the focus, never the person.', '[{"id": "f0", "type": "textarea", "label": "My most common urge moments"}, {"id": "f1", "type": "textarea", "label": "Safe alternatives I can try"}, {"id": "f2", "type": "textarea", "label": "How I will delay the decision"}, {"id": "f3", "type": "textarea", "label": "Who I can contact"}, {"id": "f4", "type": "textarea", "label": "Support available any time, including 988 by call or text"}]'::jsonb, array['addiction', 'distress tolerance', 'DBT skills']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('supporting-change-together-agreement', 'Supporting Change Together Agreement', 'couples'::resource_kind, 'Partners agree on how to support a goal around substance use without monitoring or blame.', 'Use it to help a couple build a supportive plan around substance use.', array['Couples']::text[], '30 minutes', 'Have the partner with the goal say what support looks like and the other say what they need. Discuss what to do after a hard day or a lapse. Focus on shared plans and avoid blame.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my goal and what helps"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can offer and what I need"}, {"id": "f2", "type": "textarea", "label": "What we will do on hard days"}, {"id": "f3", "type": "textarea", "label": "What we will do after a lapse"}, {"id": "f4", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['addiction', 'support', 'substance use']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('anger-cue-map', 'Anger Cue Map', 'worksheet'::resource_kind, 'A body outline where a client marks early signs of anger and numbers them by order of arrival.', 'Use it to help a client catch anger earlier.', array['Adults']::text[], '25 minutes', 'Have the client color or mark where anger shows up in the body and in what order. Then ask for the earliest cue and when they might have stepped away. Practice naming the cue aloud.', '[{"id": "f0", "type": "textarea", "label": "Where I feel anger first"}, {"id": "f1", "type": "textarea", "label": "What comes next"}, {"id": "f2", "type": "textarea", "label": "My earliest cue"}, {"id": "f3", "type": "textarea", "label": "What I can do at the first cue"}, {"id": "f4", "type": "textarea", "label": "Someone who can help me notice"}]'::jsonb, array['anger', 'body signals', 'early warning', 'anger management']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('hot-thought-slowdown', 'Hot Thought Slowdown', 'cbt'::resource_kind, 'A thought record focused on the quick interpretation behind an angry moment.', 'Use it to help a client slow down the interpretation behind anger.', array['Adults']::text[], '25 minutes', 'Take a recent angry moment and slow it down: trigger, the thought, the feeling, the action. Ask what else could be true. The aim is a wider range of interpretations, not to deny that anger happened.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "What I told myself"}, {"id": "f2", "type": "textarea", "label": "What I felt and did"}, {"id": "f3", "type": "textarea", "label": "Another way to see it"}, {"id": "f4", "type": "textarea", "label": "What I would like to do next time"}]'::jsonb, array['anger management', 'automatic thoughts', 'interpretation']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-anger-worksheet', 'Opposite Action for Anger Worksheet', 'dbt'::resource_kind, 'A worksheet that plans opposite action for anger urges when anger doesn''t fit the facts.', 'Use it to help a client choose a different action when anger is not helpful.', array['Adults']::text[], '25 minutes', 'Check the facts first and decide with the client whether anger fits. If not, plan gentle avoidance, kind actions and a softer posture. This is a skill for some moments, not a rule to suppress anger.', '[{"id": "f0", "type": "textarea", "label": "Situation"}, {"id": "f1", "type": "textarea", "label": "Do the facts fit my anger?"}, {"id": "f2", "type": "textarea", "label": "My urge"}, {"id": "f3", "type": "textarea", "label": "An opposite action"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['opposite action', 'emotion regulation', 'DBT skills', 'anger management']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('paper-volcano-cool-down-build', 'Paper Volcano Cool-Down Build', 'kids'::resource_kind, 'A child builds a paper volcano and draws what happens before, during and after it erupts.', 'Use it to help a child notice anger building and choose a cool-down.', array['Children']::text[], '30 minutes', 'The child builds or draws the volcano and marks small signs of heat at the base. The parent helps pick two cool-downs and practices them at calm times. Praise the choice to cool down, not only success.', '[{"id": "f0", "type": "textarea", "label": "How my volcano starts to warm up"}, {"id": "f1", "type": "textarea", "label": "What it looks like when it erupts"}, {"id": "f2", "type": "textarea", "label": "Two things I can do to cool down"}, {"id": "f3", "type": "textarea", "label": "What my grown-up can do"}, {"id": "f4", "type": "textarea", "label": "Where we will keep this"}]'::jsonb, array['anger', 'children', 'calming', 'anger management']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('cool-down-cards-game', 'Cool Down Cards Game', 'game'::resource_kind, 'Players draw cards for tense situations and act out calming choices, then compare choices.', 'Use it to help a group practice calm responses to common triggers.', array['Teens', 'Groups']::text[], '25 minutes', 'Deal situation cards such as a teasing comment or a lost game. Each player picks a calm choice and acts it out in turns. Others guess. Debrief on what made the choice difficult and which options felt most doable.', '[{"id": "f0", "type": "textarea", "label": "The situation I drew"}, {"id": "f1", "type": "textarea", "label": "The calm choice I tried"}, {"id": "f2", "type": "textarea", "label": "What made it hard"}, {"id": "f3", "type": "textarea", "label": "What I might use in real life"}]'::jsonb, array['anger', 'game', 'de-escalation', 'anger management']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('compulsion-time-tracker', 'Compulsion Time Tracker', 'worksheet'::resource_kind, 'A weekly tracker of time spent on rituals and the situations that set them off.', 'Use it to help a client see how much time rituals take.', array['Adults']::text[], 'One week', 'Ask the client to note roughly how long rituals last and what came before. The aim is awareness, not stopping yet. Look together for the biggest time costs and discuss what they might choose to work on first.', '[{"id": "f0", "type": "textarea", "label": "The trigger"}, {"id": "f1", "type": "textarea", "label": "The ritual"}, {"id": "f2", "type": "textarea", "label": "About how long it took"}, {"id": "f3", "type": "textarea", "label": "How anxious I felt before and after"}, {"id": "f4", "type": "textarea", "label": "What I noticed over the week"}]'::jsonb, array['OCD', 'compulsions', 'monitoring']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('uncertainty-practice-ladder', 'Uncertainty Practice Ladder', 'cbt'::resource_kind, 'A ladder of situations where the client practices tolerating not knowing, ordered by difficulty.', 'Use it to help a client plan graded practice with uncertainty.', array['Adults']::text[], '30 minutes', 'Build the ladder with the client, starting with items that feel manageable. Agree on the response to practice, such as leaving a task unchecked. Review in session how each step went, and move at their pace.', '[{"id": "f0", "type": "textarea", "label": "Step on my ladder"}, {"id": "f1", "type": "textarea", "label": "How hard it is, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I will do and not do"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "The next step"}]'::jsonb, array['OCD', 'exposure', 'response prevention']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('thoughts-are-not-instructions-practice', 'Thoughts Are Not Instructions Practice', 'act'::resource_kind, 'A practice for noticing an intrusive thought and choosing the next action by value.', 'Use it to help a client separate a thought from what they do next.', array['Adults']::text[], '20 minutes', 'Have the client name the thought as ''I''m having the thought that...'' and ask what they would like to do with their time. Explain that the thought can stay. Practice with a mild thought first.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thought"}, {"id": "f1", "type": "textarea", "label": "How I name it"}, {"id": "f2", "type": "textarea", "label": "What the thought urges me to do"}, {"id": "f3", "type": "textarea", "label": "What I choose to do instead"}, {"id": "f4", "type": "textarea", "label": "A value behind that choice"}]'::jsonb, array['OCD', 'intrusive thoughts', 'defusion']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('ocd-bully-naming-drawing', 'OCD Bully Naming Drawing', 'kids'::resource_kind, 'A child draws and names the ''bossy worry'', and a parent practices a short, calm reply.', 'Use it to help a child see worry as separate and plan not to obey it.', array['Children']::text[], '25 minutes', 'The child draws the bossy worry and writes what it demands. The parent and child practice a short reply such as ''I won''t do that today''. The parent avoids giving extra reassurance or joining rituals.', '[{"id": "f0", "type": "textarea", "label": "What my bossy worry looks like"}, {"id": "f1", "type": "textarea", "label": "What it tells me to do"}, {"id": "f2", "type": "textarea", "label": "What I say back"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will do"}, {"id": "f4", "type": "textarea", "label": "A brave thing I did"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('reassurance-and-accommodation-agreement', 'Reassurance and Accommodation Agreement', 'couples'::resource_kind, 'Partners agree on kind ways to answer repeated questions and rituals without feeding them.', 'Use it to help a couple change how they respond to reassurance requests.', array['Couples']::text[], '30 minutes', 'Review which requests the partner currently answers and how it feels for each person. Agree on a supportive script and a gradual change. Practice the script and emphasize shared goals, not criticism.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the questions or rituals I ask for help with"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I respond now"}, {"id": "f2", "type": "textarea", "label": "What we will try instead"}, {"id": "f3", "type": "textarea", "label": "A supportive phrase"}, {"id": "f4", "type": "textarea", "label": "How we will review"}]'::jsonb, array['OCD', 'reassurance', 'accommodation']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('panic-wave-notes', 'Panic Wave Notes', 'worksheet'::resource_kind, 'A record of what happened before, during and after a panic attack and what helped it pass.', 'Use it to help a client see the shape and pattern of panic.', array['Adults']::text[], 'One week', 'Fill in after each episode with brief notes. Look for triggers, timing and what the client did. Notice that the wave rose and fell, and ask what helped even slightly. Don''t search for a single cause.', '[{"id": "f0", "type": "textarea", "label": "What was happening before"}, {"id": "f1", "type": "textarea", "label": "What I felt in my body"}, {"id": "f2", "type": "textarea", "label": "What I thought"}, {"id": "f3", "type": "textarea", "label": "What I did and how long it lasted"}, {"id": "f4", "type": "textarea", "label": "What helped"}]'::jsonb, array['panic attacks', 'monitoring', 'body signals']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('body-sensation-interpretation-sheet', 'Body Sensation Interpretation Sheet', 'cbt'::resource_kind, 'A sheet that lists body sensations, the scary interpretation and a calmer, accurate one.', 'Use it to help a client rethink what body sensations mean in a panic wave.', array['Adults']::text[], '25 minutes', 'List sensations such as a racing heart and the feared meaning, then work out other explanations that fit. Rehearse the calmer statement aloud. Encourage checking with a medical professional for any physical concern.', '[{"id": "f0", "type": "textarea", "label": "A sensation I notice"}, {"id": "f1", "type": "textarea", "label": "What I fear it means"}, {"id": "f2", "type": "textarea", "label": "Other explanations that fit"}, {"id": "f3", "type": "textarea", "label": "What I will tell myself"}, {"id": "f4", "type": "textarea", "label": "What happened when I did"}]'::jsonb, array['panic attacks', 'interoception', 'interpretation']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('making-room-for-the-wave-practice', 'Making Room for the Wave Practice', 'act'::resource_kind, 'A practice for letting panic sensations rise and fall while staying with a chosen action.', 'Use it to help a client make room for sensations instead of fighting them.', array['Adults']::text[], '20 minutes', 'Teach the client to notice, breathe into and make room for the sensation, then keep doing what they were doing. Practice with a mild sensation first. Debrief on what changed when they stopped fighting.', '[{"id": "f0", "type": "textarea", "label": "Where I feel it"}, {"id": "f1", "type": "textarea", "label": "What happens when I fight it"}, {"id": "f2", "type": "textarea", "label": "What happens when I make room"}, {"id": "f3", "type": "textarea", "label": "What I want to do in my day"}, {"id": "f4", "type": "textarea", "label": "What I will try again"}]'::jsonb, array['panic attacks', 'willingness', 'acceptance']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('tipp-cheat-card-for-surges', 'TIPP Cheat Card for Surges', 'dbt'::resource_kind, 'A pocket card describing temperature, intense exercise, paced breathing and relaxation for surges.', 'Use it to help a client use body-based skills to bring arousal down.', array['Adults']::text[], '20 minutes', 'Walk through each step and practice paced breathing in session. Discuss safety with cold water or intense exercise and adjust to the client''s health. The client writes which steps they would use first.', '[{"id": "f0", "type": "textarea", "label": "Temperature: what I would use"}, {"id": "f1", "type": "textarea", "label": "Intense exercise: what I would do"}, {"id": "f2", "type": "textarea", "label": "Paced breathing: my count"}, {"id": "f3", "type": "textarea", "label": "Relaxation: what I will try"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['panic attacks', 'TIPP', 'distress tolerance']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('heart-racing-body-drawing', 'Heart Racing Body Drawing', 'kids'::resource_kind, 'A child draws what happens in their body during big scared feelings and colors a calm-down path.', 'Use it to help a child understand body signals and plan to calm.', array['Children']::text[], '25 minutes', 'The child colors where they feel scared feelings and draws a path to calm with steps. The parent practices slow breathing alongside, like blowing bubbles. Keep the explanations simple and warm.', '[{"id": "f0", "type": "textarea", "label": "Where my body feels the scared feeling"}, {"id": "f1", "type": "textarea", "label": "What it does"}, {"id": "f2", "type": "textarea", "label": "Steps on my calm path"}, {"id": "f3", "type": "textarea", "label": "Who helps me"}, {"id": "f4", "type": "textarea", "label": "What I will practice"}]'::jsonb, array['panic attacks', 'children', 'body awareness']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('ten-minute-play-plan', 'Ten-Minute Play Plan', 'worksheet'::resource_kind, 'A weekly plan for short, child-led play with no phones and no teaching.', 'Use it to help a parent build warm connection with a child.', array['Adults']::text[], 'One week', 'Suggest ten minutes a day of child-led play with the parent describing and praising instead of directing. Record how it went. Many parents find it hard not to correct, so plan for that.', '[{"id": "f0", "type": "textarea", "label": "When special time will happen"}, {"id": "f1", "type": "textarea", "label": "What my child chose"}, {"id": "f2", "type": "textarea", "label": "What I said that helped"}, {"id": "f3", "type": "textarea", "label": "What was hard"}, {"id": "f4", "type": "textarea", "label": "What I will do again"}]'::jsonb, array['parenting', 'play', 'connection']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('parent-hot-thought-check', 'Parent Hot Thought Check', 'cbt'::resource_kind, 'A thought record for the quick judgments a parent makes in tense moments.', 'Use it to help a parent see the thoughts behind reactions and try another view.', array['Adults']::text[], '25 minutes', 'Pick a recent hard moment and trace the thought, feeling and action. Ask what else might explain the child''s behavior. Keep it compassionate. Parents often carry harsh self-talk.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "What I told myself about my child or myself"}, {"id": "f2", "type": "textarea", "label": "What I felt and did"}, {"id": "f3", "type": "textarea", "label": "Another way to see it"}, {"id": "f4", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['parenting', 'thoughts', 'self-compassion']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('family-do-list-poster', 'Family Do-List Poster', 'kids'::resource_kind, 'A child and parent make a poster of a few positive family rules with drawings.', 'Use it to help a family agree on a few clear expectations.', array['Children']::text[], '40 minutes', 'The child helps choose three or four rules worded as what to do, and draws each. The parent signs too. Post it where everyone sees it and praise follow-through. Keep wording short and positive.', '[{"id": "f0", "type": "textarea", "label": "Our rule in my words"}, {"id": "f1", "type": "textarea", "label": "What it looks like"}, {"id": "f2", "type": "textarea", "label": "What happens when we follow it"}, {"id": "f3", "type": "textarea", "label": "Who helps remind us"}, {"id": "f4", "type": "textarea", "label": "Where we will hang it"}]'::jsonb, array['parenting', 'routines', 'children']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('praise-practice-role-play', 'Praise Practice Role-Play', 'game'::resource_kind, 'Parents take turns giving specific praise and responding to a child''s actor, then compare notes.', 'Use it to help parents practice labeled praise.', array['Adults', 'Groups']::text[], '20 minutes', 'In pairs, one parent plays a child doing a small helpful thing and the other gives a specific, labeled praise. Switch roles. Debrief on what felt natural and what felt awkward.', '[{"id": "f0", "type": "textarea", "label": "Praise I gave"}, {"id": "f1", "type": "textarea", "label": "Praise I received"}, {"id": "f2", "type": "textarea", "label": "What felt awkward"}, {"id": "f3", "type": "textarea", "label": "What I will say this week"}]'::jsonb, array['parenting', 'praise', 'role play']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('parenting-team-meeting-sheet', 'Parenting Team Meeting Sheet', 'couples'::resource_kind, 'Co-parents agree on one routine, one consequence and how to back each other up.', 'Use it to help partners parent as a team.', array['Couples']::text[], '30 minutes', 'Choose one issue and agree on a response ahead of time. Cover how each will step in and how they will disagree in private. Avoid undermining in front of the child. Review after a week.', '[{"id": "f0", "type": "textarea", "label": "The issue we are working on"}, {"id": "f1", "type": "textarea", "label": "The plan we both agree on"}, {"id": "f2", "type": "textarea", "label": "How I will back my partner"}, {"id": "f3", "type": "textarea", "label": "How we will disagree privately"}, {"id": "f4", "type": "textarea", "label": "When we will review"}]'::jsonb, array['parenting', 'co-parenting', 'communication']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('sleep-and-support-shift-planner', 'Sleep and Support Shift Planner', 'worksheet'::resource_kind, 'A weekly planner that splits night and day care among supporters so a parent can rest.', 'Use it to help a new parent line up rest and help.', array['Adults']::text[], 'One week', 'Map out the week with the client, naming who can cover which block. Protect one stretch of sleep. Include a plan for asking for help. Mood that is very low or unsafe thoughts should be talked through in session; share 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Nights I need coverage"}, {"id": "f1", "type": "textarea", "label": "People who can help"}, {"id": "f2", "type": "textarea", "label": "One stretch of rest I will protect"}, {"id": "f3", "type": "textarea", "label": "How I will ask for help"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'support', 'sleep']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('good-enough-parent-thoughts', 'Good Enough Parent Thoughts', 'cbt'::resource_kind, 'A thought record for ''I should be doing better'' thoughts about early parenting.', 'Use it to help a parent challenge harsh standards.', array['Adults']::text[], '25 minutes', 'List the standards the parent holds and weigh them against what is realistic with a newborn. Ask what they would say to a friend. Normalize how much is new and uncertain.', '[{"id": "f0", "type": "textarea", "label": "The ''should'' thought"}, {"id": "f1", "type": "textarea", "label": "Where I learned this standard"}, {"id": "f2", "type": "textarea", "label": "What is realistic right now"}, {"id": "f3", "type": "textarea", "label": "What a friend would hear from me"}, {"id": "f4", "type": "textarea", "label": "A good-enough thought"}]'::jsonb, array['perinatal and postpartum', 'self-criticism', 'standards']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('values-for-this-season-of-parenting', 'Values for This Season of Parenting', 'act'::resource_kind, 'A sheet connecting values to tiny actions that fit the demands of early parenting.', 'Use it to help a parent stay connected to what matters in a demanding season.', array['Adults']::text[], '25 minutes', 'Ask which values are most important right now and shrink actions to what fits the season. A five-minute walk may count. Review with compassion for what is not possible yet.', '[{"id": "f0", "type": "textarea", "label": "What matters most to me right now"}, {"id": "f1", "type": "textarea", "label": "A small action that fits today"}, {"id": "f2", "type": "textarea", "label": "What I''m letting go of for now"}, {"id": "f3", "type": "textarea", "label": "Who I''ll share this with"}, {"id": "f4", "type": "textarea", "label": "How it felt"}]'::jsonb, array['perinatal and postpartum', 'values', 'self-compassion']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-the-five-senses-for-new-parents', 'Self-Soothe with the Five Senses for New Parents', 'dbt'::resource_kind, 'A card of quick sensory soothing options that can be done with a baby nearby.', 'Use it to help a parent calm during a long day.', array['Adults']::text[], '20 minutes', 'Build a short list for each sense that can be done in a minute or two, such as a warm drink or a favorite song. Practice one in session. Make sure the list is realistic.', '[{"id": "f0", "type": "textarea", "label": "Something I can see that soothes me"}, {"id": "f1", "type": "textarea", "label": "Something I can hear"}, {"id": "f2", "type": "textarea", "label": "Something I can smell"}, {"id": "f3", "type": "textarea", "label": "Something I can taste or touch"}, {"id": "f4", "type": "textarea", "label": "When I will use one today"}]'::jsonb, array['self-soothe', 'perinatal and postpartum', 'distress tolerance']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('night-shift-fairness-and-gratitude-talk', 'Night Shift Fairness and Gratitude Talk', 'couples'::resource_kind, 'Partners share how nights and days feel and agree on a plan with a gratitude round.', 'Use it to help partners share the load and notice each other.', array['Couples']::text[], '30 minutes', 'Have each partner describe their load and what they are most tired of. Then each shares a thanks. Agree on a plan to try for a week. Keep it practical and kind.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my load this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: my load this week"}, {"id": "f2", "type": "textarea", "label": "One thanks to my partner"}, {"id": "f3", "type": "textarea", "label": "The plan we will try"}, {"id": "f4", "type": "textarea", "label": "When we will talk again"}]'::jsonb, array['perinatal and postpartum', 'fairness', 'appreciation']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('strengths-proof-folder', 'Strengths Proof Folder', 'worksheet'::resource_kind, 'A file where a client collects specific moments that show a strength in action.', 'Use it to help a client gather proof of what they do well.', array['Adults']::text[], 'One week', 'Ask for one specific entry a day: what happened and which strength it shows. Review for patterns and notice which ones the client dismisses. Keep entries factual.', '[{"id": "f0", "type": "textarea", "label": "What I did"}, {"id": "f1", "type": "textarea", "label": "The strength it shows"}, {"id": "f2", "type": "textarea", "label": "Who noticed"}, {"id": "f3", "type": "textarea", "label": "How I felt"}, {"id": "f4", "type": "textarea", "label": "What I''d like to add tomorrow"}]'::jsonb, array['self-esteem', 'strengths', 'evidence log']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('core-belief-rewrite-sheet', 'Core Belief Rewrite Sheet', 'cbt'::resource_kind, 'A page that traces a core belief, its history and a gradual, more balanced alternative.', 'Use it to help a client start loosening a harsh belief about themselves.', array['Adults']::text[], '30 minutes', 'Name the belief and what keeps it alive, then draft a more balanced version. Keep it believable. Track small events for and against over several weeks. Avoid pushing a quick change.', '[{"id": "f0", "type": "textarea", "label": "The belief about myself"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it"}, {"id": "f2", "type": "textarea", "label": "What keeps it alive"}, {"id": "f3", "type": "textarea", "label": "A more balanced version"}, {"id": "f4", "type": "textarea", "label": "Evidence I''ll collect"}]'::jsonb, array['self-esteem', 'core beliefs', 'belief change']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('self-as-context-practice', 'Self-as-Context Practice', 'act'::resource_kind, 'A practice for noticing the self that notices, separate from labels the mind hands out.', 'Use it to help a client hold labels more lightly.', array['Adults']::text[], '20 minutes', 'Ask the client to list labels and then notice who notices them. Offer the idea of the sky and the weather. Keep the language simple and invite curiosity.', '[{"id": "f0", "type": "textarea", "label": "Labels my mind gives me"}, {"id": "f1", "type": "textarea", "label": "Who notices those labels"}, {"id": "f2", "type": "textarea", "label": "What stays the same"}, {"id": "f3", "type": "textarea", "label": "How I want to act"}, {"id": "f4", "type": "textarea", "label": "What I''ll practice"}]'::jsonb, array['self-esteem', 'self-as-context', 'observing self']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('all-about-me-mobile', 'All About Me Mobile', 'kids'::resource_kind, 'A child makes a hanging mobile with cutouts of strengths, favorites and helpers.', 'Use it to help a child celebrate who they are.', array['Children']::text[], '40 minutes', 'The child cuts and decorates shapes for strengths, favorites and people who love them. The parent adds one shape too. Hang it in the child''s room and add to it over time.', '[{"id": "f0", "type": "textarea", "label": "Something I''m good at"}, {"id": "f1", "type": "textarea", "label": "Something I love"}, {"id": "f2", "type": "textarea", "label": "A person who loves me"}, {"id": "f3", "type": "textarea", "label": "Something kind I did"}, {"id": "f4", "type": "textarea", "label": "What I''d add next"}]'::jsonb, array['self-esteem', 'children', 'strengths']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('strengths-spotting-bingo', 'Strengths Spotting Bingo', 'game'::resource_kind, 'Players mark squares for strengths they see in themselves and others during the session.', 'Use it to help a group notice and name strengths.', array['Teens', 'Groups']::text[], '25 minutes', 'Hand out bingo cards with strengths such as patient or curious. Players mark squares when they notice one in themselves or others and say why. Debrief on which strength was easiest to spot in others versus themselves.', '[{"id": "f0", "type": "textarea", "label": "A strength I marked in myself"}, {"id": "f1", "type": "textarea", "label": "A strength I saw in someone else"}, {"id": "f2", "type": "textarea", "label": "The one I found hardest to claim"}, {"id": "f3", "type": "textarea", "label": "Where I''ll use a strength this week"}]'::jsonb, array['self-esteem', 'strengths', 'game']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('social-situations-ladder', 'Social Situations Ladder', 'worksheet'::resource_kind, 'A ladder of social situations from least to most daunting, with predictions and outcomes.', 'Use it to help a client plan gradual social practice.', array['Adults']::text[], '30 minutes', 'Build the ladder from small steps like a greeting. Note the predicted outcome and what happened. Choose practice steps the client picks themselves, and celebrate showing up.', '[{"id": "f0", "type": "textarea", "label": "Situation on my ladder"}, {"id": "f1", "type": "textarea", "label": "How hard it feels, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "My prediction"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "The next step"}]'::jsonb, array['social anxiety', 'hierarchy', 'exposure']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('attention-direction-experiment', 'Attention Direction Experiment', 'cbt'::resource_kind, 'An experiment that compares attention on self versus attention on others in a conversation.', 'Use it to help a client notice what happens when attention turns outward.', array['Adults']::text[], '25 minutes', 'Have the client try a short conversation once with attention on themselves and once on the other person. Compare anxiety and what they noticed. Stress that this is an experiment, not a technique to master.', '[{"id": "f0", "type": "textarea", "label": "Conversation one: focus on myself"}, {"id": "f1", "type": "textarea", "label": "Conversation two: focus on the other person"}, {"id": "f2", "type": "textarea", "label": "What I noticed in each"}, {"id": "f3", "type": "textarea", "label": "How anxious I felt in each"}, {"id": "f4", "type": "textarea", "label": "What I''ll try next"}]'::jsonb, array['social anxiety', 'attention', 'behavioral experiment']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('social-direction-compass', 'Social Direction Compass', 'act'::resource_kind, 'A page for choosing what kind of friend or colleague the client wants to be.', 'Use it to help a client let values guide social choices.', array['Adults']::text[], '25 minutes', 'Ask what qualities the client wants in their relationships, then choose small actions that show them, even when nervous. The aim is to move toward what matters, with anxiety invited along.', '[{"id": "f0", "type": "textarea", "label": "The kind of person I want to be with others"}, {"id": "f1", "type": "textarea", "label": "A small action that shows it"}, {"id": "f2", "type": "textarea", "label": "The nerves that may come"}, {"id": "f3", "type": "textarea", "label": "What I will do anyway"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['social anxiety', 'values', 'committed action']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('social-skills-role-play-with-give', 'Social Skills Role-Play with GIVE', 'dbt'::resource_kind, 'A role-play script using the GIVE skills for starting and keeping a conversation.', 'Use it to help a client practice warm, steady conversation.', array['Adults']::text[], '30 minutes', 'Rehearse with GIVE: gentle, interested, validating, easy manner. Take turns and have the client replay a scene. Give specific positive feedback. Move at the client''s pace.', '[{"id": "f0", "type": "textarea", "label": "Situation to practice"}, {"id": "f1", "type": "textarea", "label": "Gentle: what I''ll say"}, {"id": "f2", "type": "textarea", "label": "Interested: a question I''ll ask"}, {"id": "f3", "type": "textarea", "label": "Validate: how I''ll show I''m listening"}, {"id": "f4", "type": "textarea", "label": "Easy manner: how I''ll relax"}]'::jsonb, array['social anxiety', 'GIVE', 'interpersonal effectiveness']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('conversation-starters-card-game', 'Conversation Starters Card Game', 'game'::resource_kind, 'Players draw cards of light questions and practice answering and asking back.', 'Use it to help a group practice low-stakes conversation.', array['Teens', 'Groups']::text[], '25 minutes', 'Players draw a card, answer, and ask one back. Keep cards light, such as favorite foods. Let players pass. Debrief on which questions felt easiest and what made the conversation flow.', '[{"id": "f0", "type": "textarea", "label": "A question I liked"}, {"id": "f1", "type": "textarea", "label": "A question I''d ask someone new"}, {"id": "f2", "type": "textarea", "label": "What helped me answer"}, {"id": "f3", "type": "textarea", "label": "What I''ll try this week"}]'::jsonb, array['social anxiety', 'game', 'social skills']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('grief-waves-journal', 'Grief Waves Journal', 'worksheet'::resource_kind, 'A journal for noticing when grief waves arrive, what they carry and what helped.', 'Use it to help a client track the ebb and flow of grief.', array['Adults']::text[], 'One week', 'Invite short entries rather than long ones. Notice triggers, such as songs and anniversaries, and what offered comfort. There is no right way to grieve. Normalize the unpredictability of the waves.', '[{"id": "f0", "type": "textarea", "label": "When the wave came"}, {"id": "f1", "type": "textarea", "label": "What it was about"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What comforted me"}, {"id": "f4", "type": "textarea", "label": "What I need tomorrow"}]'::jsonb, array['grief and loss', 'grief', 'monitoring']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('carry-their-love-forward-practice', 'Carry Their Love Forward Practice', 'act'::resource_kind, 'A practice for naming what the client loved about the person and one way to carry it forward.', 'Use it to help a client keep a bond while living with loss.', array['Adults']::text[], '25 minutes', 'Ask what the person valued and what the client admired, and choose one action that carries it forward. Make space for sadness. Keep the pace gentle and let silence stand.', '[{"id": "f0", "type": "textarea", "label": "Who I''m remembering"}, {"id": "f1", "type": "textarea", "label": "What they valued"}, {"id": "f2", "type": "textarea", "label": "What I loved about them"}, {"id": "f3", "type": "textarea", "label": "One way I''ll carry it forward"}, {"id": "f4", "type": "textarea", "label": "What I need today"}]'::jsonb, array['grief and loss', 'continuing bonds', 'values']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('keepsake-memory-box-build', 'Keepsake Memory Box Build', 'kids'::resource_kind, 'A child decorates a box and fills it with drawings, small objects and notes about someone they miss.', 'Use it to help a child hold memories of a loved one.', array['Children']::text[], '40 minutes', 'The child decorates the box and adds items. The parent listens to the stories and shares a memory. Answer questions simply and honestly. Allow the child to come and go from the activity.', '[{"id": "f0", "type": "textarea", "label": "Who my box is for"}, {"id": "f1", "type": "textarea", "label": "A favorite memory"}, {"id": "f2", "type": "textarea", "label": "Something I''d tell them"}, {"id": "f3", "type": "textarea", "label": "Something I put in the box"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to when I miss them"}]'::jsonb, array['grief and loss', 'children', 'remembrance']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('different-grief-styles-talk', 'Different Grief Styles Talk', 'couples'::resource_kind, 'Partners share how each grieves and what support they want from each other.', 'Use it to help a couple honor different ways of grieving.', array['Couples']::text[], '30 minutes', 'Invite each partner to describe what grieving looks like for them and what they need. Differences are normal. Close with one thing each can do to support the other.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve"}, {"id": "f2", "type": "textarea", "label": "What I need from you"}, {"id": "f3", "type": "textarea", "label": "What I can offer"}, {"id": "f4", "type": "textarea", "label": "A ritual we might share"}]'::jsonb, array['grief and loss', 'couples', 'support']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('memory-sharing-circle-game', 'Memory Sharing Circle Game', 'game'::resource_kind, 'Players pass an object and share a short memory or quality of someone they miss, or pass.', 'Use it to help a group share memories in a gentle, paced way.', array['Teens', 'Groups']::text[], '30 minutes', 'Sit in a circle with an object. Holders share a short memory or pass. Others respond with ''thank you for sharing''. Keep time limited. Debrief on what it was like to share and to hear others.', '[{"id": "f0", "type": "textarea", "label": "A memory I shared"}, {"id": "f1", "type": "textarea", "label": "What I heard from others"}, {"id": "f2", "type": "textarea", "label": "What it was like"}, {"id": "f3", "type": "textarea", "label": "What I need after this"}]'::jsonb, array['grief and loss', 'remembrance', 'game']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('relationship-patterns-map', 'Relationship Patterns Map', 'worksheet'::resource_kind, 'A map of recurring patterns in a client''s relationships, what triggers them and what they need.', 'Use it to help a client see repeating patterns across relationships.', array['Adults']::text[], '30 minutes', 'Draw a simple map of a recurring pattern, with trigger, reaction and result. Explore needs underneath. Keep to behavior and avoid labeling people.', '[{"id": "f0", "type": "textarea", "label": "A pattern I notice"}, {"id": "f1", "type": "textarea", "label": "What sets it off"}, {"id": "f2", "type": "textarea", "label": "What I do"}, {"id": "f3", "type": "textarea", "label": "What happens next"}, {"id": "f4", "type": "textarea", "label": "What I need instead"}]'::jsonb, array['relationship issues', 'patterns', 'needs']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('validation-practice-sheet', 'Validation Practice Sheet', 'dbt'::resource_kind, 'A sheet of the levels of validation with space to practice each in a relationship.', 'Use it to help a client practice validating others and themselves.', array['Adults']::text[], '25 minutes', 'Go through levels such as paying attention, reflecting and acknowledging. Role-play a short scene. Many clients confuse validation with agreement, so name the difference.', '[{"id": "f0", "type": "textarea", "label": "Someone I want to validate"}, {"id": "f1", "type": "textarea", "label": "What I''ll say"}, {"id": "f2", "type": "textarea", "label": "What they might feel"}, {"id": "f3", "type": "textarea", "label": "How I''ll show I''m listening"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['validation', 'interpersonal effectiveness', 'DBT skills', 'relationship issues']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('cycle-mapping-together', 'Cycle Mapping Together', 'couples'::resource_kind, 'Partners draw their negative cycle, from trigger to reaction to reaction, and name the cycle as the problem.', 'Use it to help a couple see the cycle as the shared problem.', array['Couples']::text[], '40 minutes', 'On a big page, draw each partner''s trigger, feeling and action, and how each sets off the other. Give the cycle a name. Treat the cycle as the opponent, not either person.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I feel and do"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I feel and do"}, {"id": "f2", "type": "textarea", "label": "How each sets off the other"}, {"id": "f3", "type": "textarea", "label": "A name for our cycle"}, {"id": "f4", "type": "textarea", "label": "How we''ll step out of it"}]'::jsonb, array['relationship issues', 'EFT', 'cycle']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('soft-start-up-rewrite', 'Soft Start-Up Rewrite', 'couples'::resource_kind, 'Partners rewrite harsh openers into gentle ones with a feeling, a situation and a request.', 'Use it to help a couple start hard talks more gently.', array['Couples']::text[], '25 minutes', 'Take a real complaint and rewrite it as ''I feel... about... I need...''. Practice in session and give feedback. Notice tone and body language. Repeat until it feels natural.', '[{"id": "f0", "type": "textarea", "label": "Harsh opener from Partner A"}, {"id": "f1", "type": "textarea", "label": "Soft rewrite"}, {"id": "f2", "type": "textarea", "label": "Harsh opener from Partner B"}, {"id": "f3", "type": "textarea", "label": "Soft rewrite"}, {"id": "f4", "type": "textarea", "label": "How it felt to hear it"}]'::jsonb, array['soft start-up', 'Gottman', 'communication', 'relationship issues']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('perspective-swap-role-play', 'Perspective Swap Role-Play', 'game'::resource_kind, 'Pairs act out a disagreement from the other person''s side, then debrief on what they learned.', 'Use it to help a group practice seeing another view.', array['Teens', 'Groups']::text[], '25 minutes', 'Pairs choose a mild disagreement and swap roles. After a short scene, each says what it felt like to speak as the other. Debrief on what they might change.', '[{"id": "f0", "type": "textarea", "label": "The disagreement"}, {"id": "f1", "type": "textarea", "label": "What I felt in the other role"}, {"id": "f2", "type": "textarea", "label": "What I understand now"}, {"id": "f3", "type": "textarea", "label": "What I''d say differently"}]'::jsonb, array['relationship issues', 'perspective-taking', 'game']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('safety-and-support-circle', 'Safety and Support Circle', 'worksheet'::resource_kind, 'A sheet for listing trusted people, safe spaces and ways to reach help, without any account of events.', 'Use it to help a client map support and safety now.', array['Adults']::text[], '25 minutes', 'This is about the present: who to turn to and where to feel safe. Do not ask for details of what happened. Include a crisis line such as 988 (call or text). Let the client set the pace and stop when needed.', '[{"id": "f0", "type": "textarea", "label": "People I trust"}, {"id": "f1", "type": "textarea", "label": "Places I feel safe"}, {"id": "f2", "type": "textarea", "label": "How I reach them"}, {"id": "f3", "type": "textarea", "label": "Support available any time, including 988 by call or text"}, {"id": "f4", "type": "textarea", "label": "What I''d like my circle to know"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('pacing-and-grounding-plan', 'Pacing and Grounding Plan', 'dbt'::resource_kind, 'A plan for pacing work with a sense of control, with grounding skills for moments of overwhelm.', 'Use it to help a client set a pace they choose.', array['Adults']::text[], '30 minutes', 'Work out signals for slowing down, such as a hand gesture, and grounding skills to use. Give the client the right to say stop. Keep the focus on present safety and choice.', '[{"id": "f0", "type": "textarea", "label": "How I''ll signal I need a pause"}, {"id": "f1", "type": "textarea", "label": "Grounding skills I can use"}, {"id": "f2", "type": "textarea", "label": "Things that help me feel in control"}, {"id": "f3", "type": "textarea", "label": "What I need from sessions"}, {"id": "f4", "type": "textarea", "label": "Who I''ll contact if I feel unsafe"}]'::jsonb, array['sexual abuse', 'grounding', 'pacing']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('values-and-choice-practice', 'Values and Choice Practice', 'act'::resource_kind, 'A practice for identifying values and small chosen actions that restore a sense of agency.', 'Use it to help a client reclaim choice in daily life.', array['Adults']::text[], '25 minutes', 'Focus on what matters now and small choices the client can make. Avoid asking for details of past events. Celebrate decisions, however small, and let the client lead.', '[{"id": "f0", "type": "textarea", "label": "A value that matters to me"}, {"id": "f1", "type": "textarea", "label": "A choice I can make today"}, {"id": "f2", "type": "textarea", "label": "What I feel when I choose"}, {"id": "f3", "type": "textarea", "label": "Who supports me"}, {"id": "f4", "type": "textarea", "label": "What I''ll try this week"}]'::jsonb, array['sexual abuse', 'values', 'agency']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('my-body-is-mine-poster', 'My Body Is Mine Poster', 'kids'::resource_kind, 'A child draws a poster of body safety rules and a circle of trusted grown-ups.', 'Use it to help a child learn that their body belongs to them and who to tell.', array['Children']::text[], '30 minutes', 'The child draws the rules in simple words, such as ''my body is mine'', and names trusted adults. Remember your reporting duties if a child discloses, and respond calmly without leading questions. The parent reinforces the rules.', '[{"id": "f0", "type": "textarea", "label": "My body belongs to me"}, {"id": "f1", "type": "textarea", "label": "People I can tell if something feels wrong"}, {"id": "f2", "type": "textarea", "label": "What I can say"}, {"id": "f3", "type": "textarea", "label": "How I feel safe"}, {"id": "f4", "type": "textarea", "label": "Where we''ll hang this"}]'::jsonb, array['sexual abuse', 'body safety', 'children']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('intimacy-pacing-agreement', 'Intimacy Pacing Agreement', 'couples'::resource_kind, 'Partners agree on signals, pauses and consent practices that give a survivor control over pace.', 'Use it to help partners build trust and choice in closeness.', array['Couples']::text[], '30 minutes', 'The partner who is a survivor leads on what feels okay, and both agree on a stop signal and no pressure. Talk about affection in general terms. Keep the discussion on safety and consent, not on past events.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me feel safe"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I''ll respect that"}, {"id": "f2", "type": "textarea", "label": "Our stop signal"}, {"id": "f3", "type": "textarea", "label": "Ways to connect without pressure"}, {"id": "f4", "type": "textarea", "label": "When we''ll check in"}]'::jsonb, array['sexual abuse', 'consent', 'trust']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('coping-toolbox-builder', 'Coping Toolbox Builder', 'worksheet'::resource_kind, 'A page to sort coping tools by situation, such as body, mind, people and place.', 'Use it to help a client build a personal set of tools.', array['Adults']::text[], '25 minutes', 'Fill in tools the client already uses and a few to try. Sort by situation. Test one in session. Keep a copy on a phone or wallet card.', '[{"id": "f0", "type": "textarea", "label": "Tools for my body"}, {"id": "f1", "type": "textarea", "label": "Tools for my mind"}, {"id": "f2", "type": "textarea", "label": "Tools involving people"}, {"id": "f3", "type": "textarea", "label": "Tools for a place"}, {"id": "f4", "type": "textarea", "label": "The one I''ll try first"}]'::jsonb, array['coping skills', 'skills', 'resources']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('steady-self-talk-pocket-card', 'Steady Self-Talk Pocket Card', 'cbt'::resource_kind, 'A card of short, believable coping statements written for hard moments.', 'Use it to help a client prepare helpful self-talk.', array['Adults']::text[], '20 minutes', 'Collect statements the client believes, such as ''This is hard, and I''ve handled hard before''. Rehearse. Test them in a mild situation first. Drop those that feel hollow.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I expect"}, {"id": "f1", "type": "textarea", "label": "A coping thought I believe"}, {"id": "f2", "type": "textarea", "label": "A second one"}, {"id": "f3", "type": "textarea", "label": "Where I''ll keep them"}, {"id": "f4", "type": "textarea", "label": "How they worked"}]'::jsonb, array['coping skills', 'self-talk', 'cope ahead']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('self-soothe-kit-inventory', 'Self-Soothe Kit Inventory', 'dbt'::resource_kind, 'A list of items for a soothing kit organized by the five senses.', 'Use it to help a client assemble a kit for tough moments.', array['Adults']::text[], '25 minutes', 'Choose one or two items per sense and assemble a kit, physical or digital. Practice one in session. Discuss when to use it and where to keep it.', '[{"id": "f0", "type": "textarea", "label": "Sight"}, {"id": "f1", "type": "textarea", "label": "Sound"}, {"id": "f2", "type": "textarea", "label": "Smell"}, {"id": "f3", "type": "textarea", "label": "Taste"}, {"id": "f4", "type": "textarea", "label": "Touch"}, {"id": "f5", "type": "textarea", "label": "Where I''ll keep my kit"}]'::jsonb, array['self-soothe', 'distress tolerance', 'DBT skills', 'coping skills']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('skill-spinner-wheel-build', 'Skill Spinner Wheel Build', 'kids'::resource_kind, 'A child makes a spinner with coping ideas and spins it when feelings are big.', 'Use it to help a child choose a coping idea in play.', array['Children']::text[], '30 minutes', 'The child draws or writes coping ideas on a paper wheel and adds a spinner. The parent practices spinning at calm times and joins in. Praise trying, not only success.', '[{"id": "f0", "type": "textarea", "label": "Ideas on my spinner"}, {"id": "f1", "type": "textarea", "label": "My favorite"}, {"id": "f2", "type": "textarea", "label": "One I want to try"}, {"id": "f3", "type": "textarea", "label": "When I''ll spin it"}, {"id": "f4", "type": "textarea", "label": "Who plays with me"}]'::jsonb, array['coping skills', 'children', 'craft']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('coping-skills-charades-relay', 'Coping Skills Charades Relay', 'game'::resource_kind, 'Teams act out skills and race to guess them, then say when they could use each.', 'Use it to help a group remember and practice skills.', array['Teens', 'Groups']::text[], '25 minutes', 'Write skills on cards and act them out in teams, with a guess limit. After each guess the actor says when they might use it. Debrief on which skills felt most useful.', '[{"id": "f0", "type": "textarea", "label": "Skills I guessed"}, {"id": "f1", "type": "textarea", "label": "A skill I forgot"}, {"id": "f2", "type": "textarea", "label": "A time I could use one"}, {"id": "f3", "type": "textarea", "label": "What I''ll try"}]'::jsonb, array['coping skills', 'game', 'skills']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('fear-hierarchy-builder', 'Fear Hierarchy Builder', 'worksheet'::resource_kind, 'A sheet for ranking feared situations by difficulty to plan gradual practice.', 'Use it to help a client build a ladder of steps.', array['Adults']::text[], '30 minutes', 'List situations related to the fear and rate each from 0 to 100. Pick steps spaced evenly. The client chooses the pace. Rehearse safety in session.', '[{"id": "f0", "type": "textarea", "label": "Feared situations"}, {"id": "f1", "type": "textarea", "label": "Difficulty ratings"}, {"id": "f2", "type": "textarea", "label": "The first step"}, {"id": "f3", "type": "textarea", "label": "What I''ll do to prepare"}, {"id": "f4", "type": "textarea", "label": "Who supports me"}]'::jsonb, array['phobias', 'hierarchy', 'exposure']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('fear-prediction-check', 'Fear Prediction Check', 'cbt'::resource_kind, 'A form that records predictions before a practice step and compares them with outcomes.', 'Use it to help a client test fearful predictions.', array['Adults']::text[], '20 minutes', 'Before a step, write the prediction and its likelihood. After, record what happened. Compare and discuss. Keep steps small and repeatable.', '[{"id": "f0", "type": "textarea", "label": "Step I''ll take"}, {"id": "f1", "type": "textarea", "label": "What I predict"}, {"id": "f2", "type": "textarea", "label": "How likely, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['phobias', 'predictions', 'behavioral experiment']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('approach-with-fear-along-practice', 'Approach with Fear Along Practice', 'act'::resource_kind, 'A practice for taking a step toward a feared thing with the feeling allowed to come.', 'Use it to help a client move toward what matters while afraid.', array['Adults']::text[], '25 minutes', 'Ask the client to name the value behind facing the fear and to carry the fear along. Choose a step and practice with willingness. Review how it felt to move with the fear.', '[{"id": "f0", "type": "textarea", "label": "Why this matters to me"}, {"id": "f1", "type": "textarea", "label": "The step I''ll take"}, {"id": "f2", "type": "textarea", "label": "The fear I''ll carry"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['phobias', 'willingness', 'approach']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('fear-facing-sticker-chart', 'Fear Facing Sticker Chart', 'kids'::resource_kind, 'A child decorates a chart of tiny steps toward a feared thing and adds stickers after each try.', 'Use it to help a child take gradual steps with cheering from a parent.', array['Children']::text[], '30 minutes', 'The child draws the chart and lists tiny steps. The parent encourages effort and doesn''t push. Add stickers for trying. Review and adjust steps.', '[{"id": "f0", "type": "textarea", "label": "The thing I''m scared of"}, {"id": "f1", "type": "textarea", "label": "My first tiny step"}, {"id": "f2", "type": "textarea", "label": "The next step"}, {"id": "f3", "type": "textarea", "label": "How I felt"}, {"id": "f4", "type": "textarea", "label": "Who cheers for me"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('brave-step-dice-roll', 'Brave Step Dice Roll', 'game'::resource_kind, 'Players roll dice to choose a small brave step from a list and cheer for each other.', 'Use it to help a group take light, playful steps toward fears.', array['Teens', 'Groups']::text[], '25 minutes', 'Write brave steps on a numbered list, each linked to a die roll. Players pick their own list ahead of time. Cheer for trying. Debrief on what it was like to try.', '[{"id": "f0", "type": "textarea", "label": "My brave step"}, {"id": "f1", "type": "textarea", "label": "How it felt before"}, {"id": "f2", "type": "textarea", "label": "How it felt after"}, {"id": "f3", "type": "textarea", "label": "A step I''ll try this week"}]'::jsonb, array['phobias', 'game', 'approach']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('body-gratitude-for-what-it-does', 'Body Gratitude for What It Does', 'worksheet'::resource_kind, 'A sheet that lists things the body helps the client do and enjoy.', 'Use it to help a client value what their body does.', array['Adults']::text[], '20 minutes', 'Ask for things the body enables, such as hugging or dancing. Avoid appearance. Review which items surprise the client. Add one a day.', '[{"id": "f0", "type": "textarea", "label": "Things my body helps me do"}, {"id": "f1", "type": "textarea", "label": "Something I enjoyed today"}, {"id": "f2", "type": "textarea", "label": "A way I''ll thank my body"}, {"id": "f3", "type": "textarea", "label": "Who I do these with"}, {"id": "f4", "type": "textarea", "label": "What I notice"}]'::jsonb, array['body image', 'gratitude', 'self-compassion']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('appearance-hot-thought-log', 'Appearance Hot Thought Log', 'cbt'::resource_kind, 'A thought record for harsh thoughts about appearance, with a kinder, balanced reply.', 'Use it to help a client examine harsh appearance thoughts.', array['Adults']::text[], '25 minutes', 'Choose a recent moment, the thought and the feeling. Ask what a friend would hear. Don''t debate how the client looks; focus on how the thought affects them.', '[{"id": "f0", "type": "textarea", "label": "The moment"}, {"id": "f1", "type": "textarea", "label": "The thought"}, {"id": "f2", "type": "textarea", "label": "How it made me feel"}, {"id": "f3", "type": "textarea", "label": "What I''d tell a friend"}, {"id": "f4", "type": "textarea", "label": "A kinder reply"}]'::jsonb, array['body image', 'thought record', 'self-criticism']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('values-over-appearance-choice-point', 'Values Over Appearance Choice Point', 'act'::resource_kind, 'A choice-point sheet for moments when appearance worries steer a decision.', 'Use it to help a client choose valued actions over appearance worries.', array['Adults']::text[], '25 minutes', 'Describe a moment when worry about appearance led to avoiding something, and what the client would do if guided by a value. Plan a small step.', '[{"id": "f0", "type": "textarea", "label": "The moment"}, {"id": "f1", "type": "textarea", "label": "What worry told me to do"}, {"id": "f2", "type": "textarea", "label": "The value I care about"}, {"id": "f3", "type": "textarea", "label": "A step toward it"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['body image', 'choice point', 'values']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('mindful-description-without-judgment', 'Mindful Description Without Judgment', 'dbt'::resource_kind, 'A practice for describing sensations and experiences without judgmental words.', 'Use it to help a client practice a nonjudgmental stance toward themselves.', array['Adults']::text[], '20 minutes', 'Have the client describe an experience, such as the feel of a warm shower, using facts only. When judgments come up, notice and return. Keep the focus on sensations and actions.', '[{"id": "f0", "type": "textarea", "label": "Something I experienced"}, {"id": "f1", "type": "textarea", "label": "Facts only"}, {"id": "f2", "type": "textarea", "label": "Judgments that came up"}, {"id": "f3", "type": "textarea", "label": "How I let them go"}, {"id": "f4", "type": "textarea", "label": "What I''ll practice"}]'::jsonb, array['body image', 'nonjudgmental stance', 'mindfulness']::text[], '2026-10-11T15:00:00+00:00'::timestamptz),
  ('kind-words-mirror-craft', 'Kind Words Mirror Craft', 'kids'::resource_kind, 'A child decorates a paper mirror frame and adds kind words about who they are and what they do.', 'Use it to help a child hear and say kind words about themselves.', array['Children']::text[], '30 minutes', 'The child decorates the frame and writes kind words about actions and character. The parent adds one. Keep comments off looks. Hang it where the child will see it.', '[{"id": "f0", "type": "textarea", "label": "Kind words about me"}, {"id": "f1", "type": "textarea", "label": "What I''m good at"}, {"id": "f2", "type": "textarea", "label": "What my grown-up says"}, {"id": "f3", "type": "textarea", "label": "How I feel"}, {"id": "f4", "type": "textarea", "label": "Where we''ll hang it"}]'::jsonb, array['body image', 'children', 'self-talk']::text[], '2026-10-11T15:00:00+00:00'::timestamptz)
